CREATE TABLE person_voice_assets(
 id uuid PRIMARY KEY,account_id uuid NOT NULL REFERENCES media_account_write_gates(account_id),draft_id uuid NOT NULL,
 declared_mime text NOT NULL CHECK(declared_mime IN('audio/wav','audio/mpeg','audio/ogg','audio/webm','audio/mp4')),declared_bytes integer NOT NULL CHECK(declared_bytes BETWEEN 1 AND 8388608),input_sha256 text NOT NULL CHECK(input_sha256~'^[a-f0-9]{64}$'),
 status text NOT NULL DEFAULT 'awaiting_upload' CHECK(status IN('awaiting_upload','verifying','ready','rejected','revoked','deleted')),recovery_blocked boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1 CHECK(version>0),account_access_version integer NOT NULL CHECK(account_access_version>0),story_authorization_version integer NOT NULL CHECK(story_authorization_version>0),voice_authorization_version integer NOT NULL CHECK(voice_authorization_version>0),
 object_key text UNIQUE,mime_type text CHECK(mime_type='audio/wav'),byte_size integer CHECK(byte_size BETWEEN 46 AND 1440044 AND (byte_size-44)%2=0),sha256 text CHECK(sha256~'^[a-f0-9]{64}$'),duration_ms integer CHECK(duration_ms BETWEEN 1 AND 30000),failure_code text,
 created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),verified_at timestamptz(3),revoked_at timestamptz(3),deleted_at timestamptz(3),
 UNIQUE(account_id,id),UNIQUE(account_id,id,draft_id),CHECK(status<>'ready' OR(object_key IS NOT NULL AND mime_type IS NOT NULL AND byte_size IS NOT NULL AND sha256 IS NOT NULL AND duration_ms IS NOT NULL AND verified_at IS NOT NULL)),CHECK(status NOT IN('revoked','deleted') OR revoked_at IS NOT NULL),CHECK(status<>'deleted' OR deleted_at IS NOT NULL)
);
CREATE TABLE person_voice_upload_slots(
 id uuid PRIMARY KEY,account_id uuid NOT NULL,voice_id uuid NOT NULL,staging_key text NOT NULL UNIQUE,state text NOT NULL DEFAULT 'active' CHECK(state IN('active','uploading','uploaded','completed','expired','revoked')),
 upload_key uuid,attempt_id uuid,lease_until timestamptz(3),expires_at timestamptz(3) NOT NULL,created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),uploaded_at timestamptz(3),ended_at timestamptz(3),input_deleted_at timestamptz(3),cleanup_checked_at timestamptz(3),
 FOREIGN KEY(account_id,voice_id) REFERENCES person_voice_assets(account_id,id),UNIQUE(account_id,voice_id,id),CHECK((state='uploading')=(attempt_id IS NOT NULL AND lease_until IS NOT NULL)),CHECK(state<>'uploaded' OR uploaded_at IS NOT NULL),CHECK((state IN('completed','expired','revoked'))=(ended_at IS NOT NULL)),CHECK(expires_at>created_at)
);
CREATE UNIQUE INDEX person_voice_current_slot ON person_voice_upload_slots(account_id,voice_id) WHERE state IN('active','uploading','uploaded');
CREATE TABLE person_voice_jobs(
 id uuid PRIMARY KEY,account_id uuid NOT NULL,voice_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('verify','purge')),voice_version integer NOT NULL CHECK(voice_version>0),state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','running','succeeded','failed','blocked')),
 attempt_id uuid,attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count>=0 AND attempt_count<=CASE WHEN kind='verify' THEN 5 ELSE 20 END),lease_until timestamptz(3),retry_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),output_key text,output_keys text[] NOT NULL DEFAULT '{}',failure_code text,created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),started_at timestamptz(3),finished_at timestamptz(3),
 FOREIGN KEY(account_id,voice_id) REFERENCES person_voice_assets(account_id,id),UNIQUE(account_id,voice_id,kind),CHECK((state='running')=(attempt_id IS NOT NULL AND lease_until IS NOT NULL)),CHECK(state NOT IN('succeeded','blocked') OR finished_at IS NOT NULL)
);
CREATE TABLE person_voice_grants(account_id uuid NOT NULL,voice_id uuid NOT NULL,draft_id uuid NOT NULL,voice_version integer NOT NULL CHECK(voice_version>0),bind_revision integer NOT NULL DEFAULT 1 CHECK(bind_revision>0),source_binding_version integer NOT NULL CHECK(source_binding_version>=0),binding_until timestamptz(3) NOT NULL,state text NOT NULL DEFAULT 'active' CHECK(state IN('active','revoked')),created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),candidate_until timestamptz(3) NOT NULL DEFAULT clock_timestamp()+interval '30 minutes',confirmed_at timestamptz(3),revoked_at timestamptz(3),PRIMARY KEY(account_id,voice_id),FOREIGN KEY(account_id,voice_id,draft_id) REFERENCES person_voice_assets(account_id,id,draft_id),CHECK((state='revoked')=(revoked_at IS NOT NULL)));
CREATE TABLE person_voice_commands(account_id uuid NOT NULL REFERENCES media_account_write_gates(account_id),operation text NOT NULL CHECK(operation IN('create','slot','complete','delete')),idempotency_key uuid NOT NULL,voice_id uuid NOT NULL,slot_id uuid,request_hash text NOT NULL CHECK(request_hash~'^[a-f0-9]{64}$'),created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(account_id,operation,idempotency_key));
CREATE FUNCTION person_voice_write_gate() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE erased timestamptz;blocked boolean;BEGIN
 IF TG_OP='UPDATE' AND NEW.account_id<>OLD.account_id THEN RAISE EXCEPTION 'immutable voice account' USING ERRCODE='42501';END IF;
 SELECT erased_at INTO erased FROM media_account_write_gates WHERE account_id=NEW.account_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'missing voice account gate' USING ERRCODE='42501';END IF;
 IF TG_TABLE_NAME='person_voice_assets' AND TG_OP='UPDATE' THEN IF NOT OLD.recovery_blocked AND NEW.recovery_blocked AND(to_jsonb(NEW)-'recovery_blocked')=(to_jsonb(OLD)-'recovery_blocked') THEN RETURN NEW;END IF;END IF;
 IF TG_TABLE_NAME='person_voice_assets' THEN blocked=NEW.status NOT IN('rejected','revoked','deleted');ELSIF TG_TABLE_NAME='person_voice_upload_slots' THEN blocked=NEW.state NOT IN('expired','revoked');ELSIF TG_TABLE_NAME='person_voice_jobs' THEN blocked=NEW.state IN('queued','running');ELSIF TG_TABLE_NAME='person_voice_grants' THEN blocked=NEW.state='active';ELSE blocked=true;END IF;
 IF erased IS NOT NULL AND blocked THEN RAISE EXCEPTION 'voice account erased' USING ERRCODE='42501';END IF;RETURN NEW;END$$;
CREATE TRIGGER person_voice_assets_gate BEFORE INSERT OR UPDATE ON person_voice_assets FOR EACH ROW EXECUTE FUNCTION person_voice_write_gate();
CREATE TRIGGER person_voice_slots_gate BEFORE INSERT OR UPDATE ON person_voice_upload_slots FOR EACH ROW EXECUTE FUNCTION person_voice_write_gate();
CREATE TRIGGER person_voice_jobs_gate BEFORE INSERT OR UPDATE ON person_voice_jobs FOR EACH ROW EXECUTE FUNCTION person_voice_write_gate();
CREATE TRIGGER person_voice_grants_gate BEFORE INSERT OR UPDATE ON person_voice_grants FOR EACH ROW EXECUTE FUNCTION person_voice_write_gate();
CREATE TRIGGER person_voice_commands_gate BEFORE INSERT OR UPDATE ON person_voice_commands FOR EACH ROW EXECUTE FUNCTION person_voice_write_gate();
CREATE FUNCTION person_voice_immutable() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF TG_OP='DELETE' THEN IF EXISTS(SELECT 1 FROM media_account_write_gates WHERE account_id=OLD.account_id AND erased_at IS NOT NULL) THEN RETURN OLD;END IF;RAISE EXCEPTION 'voice acceptance requires account erasure' USING ERRCODE='42501';END IF;
 IF TG_TABLE_NAME='person_voice_commands' OR TG_TABLE_NAME='person_voice_assets' AND(to_jsonb(NEW)-ARRAY['status','recovery_blocked','version','object_key','mime_type','byte_size','sha256','duration_ms','failure_code','updated_at','verified_at','revoked_at','deleted_at'])<>(to_jsonb(OLD)-ARRAY['status','recovery_blocked','version','object_key','mime_type','byte_size','sha256','duration_ms','failure_code','updated_at','verified_at','revoked_at','deleted_at']) THEN RAISE EXCEPTION 'voice acceptance is immutable' USING ERRCODE='42501';END IF;
 IF TG_TABLE_NAME='person_voice_assets' THEN IF OLD.recovery_blocked AND NOT NEW.recovery_blocked THEN RAISE EXCEPTION 'restored voice is blocked' USING ERRCODE='42501';END IF;IF OLD.object_key IS NOT NULL AND(NEW.object_key,NEW.mime_type,NEW.byte_size,NEW.sha256,NEW.duration_ms) IS DISTINCT FROM(OLD.object_key,OLD.mime_type,OLD.byte_size,OLD.sha256,OLD.duration_ms) THEN RAISE EXCEPTION 'verified voice is immutable' USING ERRCODE='42501';END IF;END IF;RETURN NEW;END$$;
CREATE TRIGGER person_voice_asset_immutable BEFORE UPDATE OR DELETE ON person_voice_assets FOR EACH ROW EXECUTE FUNCTION person_voice_immutable();
CREATE TRIGGER person_voice_command_immutable BEFORE UPDATE OR DELETE ON person_voice_commands FOR EACH ROW EXECUTE FUNCTION person_voice_immutable();
